// dimensionalAudio.js
// Zero-latency lossless Base64 WAV soundscapes for portal transitions
window.PORTAL_AUDIO = {
    space: 'data:audio/wav;base64,',
    fintech: 'data:audio/wav;base64,',
    vanilla: 'data:audio/wav;base64,'
};

window.playDimensionAudio = function(realm) {
    try {
        var src = window.PORTAL_AUDIO && window.PORTAL_AUDIO[realm];
        if (!src) return;
        var audio = new Audio(src);
        audio.volume = (window.SystemAPI && typeof window.SystemAPI.getVolume === "function") ? window.SystemAPI.getVolume() : 0.75;
        var p = audio.play();
        if (p && typeof p.catch === "function") p.catch(function() {});
    } catch (_) {}
};
